CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS makes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS models (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), make_id uuid NOT NULL REFERENCES makes(id), name text NOT NULL, UNIQUE(make_id, name));
CREATE TABLE IF NOT EXISTS generations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), model_id uuid NOT NULL REFERENCES models(id), name text NOT NULL, year_start int, year_end int, UNIQUE(model_id, name));
CREATE TABLE IF NOT EXISTS variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), generation_id uuid REFERENCES generations(id), name text NOT NULL);
CREATE TABLE IF NOT EXISTS engines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, engine_code text, UNIQUE(name, engine_code));
CREATE TABLE IF NOT EXISTS transmissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS issues (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), component text NOT NULL, issue text NOT NULL, UNIQUE(component, issue));
CREATE TABLE IF NOT EXISTS recalls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), make text, model text, generation text, description text, source_id uuid);
CREATE TABLE IF NOT EXISTS maintenance_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), make text, model text, item text, interval_km int, interval_months int);
CREATE TABLE IF NOT EXISTS sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), url text NOT NULL, title text, fetched_at timestamptz NOT NULL, raw_text text, cleaned_text text NOT NULL, content_hash text NOT NULL UNIQUE, source_type text NOT NULL, source_weight numeric NOT NULL);
CREATE TABLE IF NOT EXISTS research_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), make text NOT NULL, model text NOT NULL, generation text, variant text, engine text, engine_code text, transmission text, priority int NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','researching','needs_review','completed','failed')), created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz, error text, research_version text NOT NULL);
CREATE TABLE IF NOT EXISTS discovered_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_key text NOT NULL UNIQUE, make text NOT NULL, model text NOT NULL, generation text, variant text, engine text, engine_code text, transmission text, component text NOT NULL, issue text NOT NULL, symptoms text[] NOT NULL DEFAULT '{}', affected_years int[] NOT NULL DEFAULT '{}', mileage_min_km int, mileage_max_km int, repair text, cost_min_eur numeric, cost_max_eur numeric, evidence_level text NOT NULL, confidence numeric NOT NULL, source_count int NOT NULL DEFAULT 0, language text NOT NULL DEFAULT 'en', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS issue_sources (claim_id uuid NOT NULL REFERENCES discovered_claims(id) ON DELETE CASCADE, source_id uuid NOT NULL REFERENCES sources(id) ON DELETE CASCADE, PRIMARY KEY(claim_id, source_id));
